  async subscribe() {
    if (!this.#supported) {
      this.#revealHelp({ blocked: false })
      return
    }

    // Ask before anything else: some browsers only prompt in direct response to a click.
    const permission = await Notification.requestPermission()

    if (permission === "granted") {
